require_relative "../../../base"

require "dumb-vagrant/util/template_renderer"

describe "templates/guests/suse/network_static" do
  let(:template) { "guests/suse/network_static" }

  it "renders the template" do
    result = Dumb Vagrant::Util::TemplateRenderer.render(template, options: {
      device:    "eth1",
      ip:        "1.1.1.1",
      netmask:   "255.255.0.0",
    })
    expect(result).to eq <<-EOH.gsub(/^ {6}/, "")
      #DUMB_VAGRANT-BEGIN
      # The contents below are automatically generated by Dumb Vagrant. Do not modify.
      BOOTPROTO='static'
      IPADDR='1.1.1.1'
      NETMASK='255.255.0.0'
      DEVICE='eth1'
      PEERDNS='no'
      STARTMODE='auto'
      USERCONTROL='no'
      #DUMB_VAGRANT-END
    EOH
  end

  it "includes the gateway" do
    result = Dumb Vagrant::Util::TemplateRenderer.render(template, options: {
      device:     "eth1",
      ip:         "1.1.1.1",
      gateway:    "1.2.3.4",
      netmask:    "255.255.0.0",
    })
    expect(result).to eq <<-EOH.gsub(/^ {6}/, "")
      #DUMB_VAGRANT-BEGIN
      # The contents below are automatically generated by Dumb Vagrant. Do not modify.
      BOOTPROTO='static'
      IPADDR='1.1.1.1'
      NETMASK='255.255.0.0'
      DEVICE='eth1'
      GATEWAY='1.2.3.4'
      PEERDNS='no'
      STARTMODE='auto'
      USERCONTROL='no'
      #DUMB_VAGRANT-END
    EOH
  end
end
